  "Stake. Save.": { es:"Haz staking. Ahorra.", de:"Staken. Sparen.", nl:"Stake. Bespaar.", uk:"Стейкайте. Заощаджуйте.", ru:"Стейкайте. Экономьте.", fr:"Stakez. Économisez.", pt:"Faça staking. Poupe.", zh:"质押。省钱。", ko:"스테이킹. 절약." },
